from fastapi import FastAPI, Header
from fastapi.testclient import TestClient
from pydantic import BaseModel

app = FastAPI()

class MyHeaders(BaseModel):
    my_header: str | None = None

@app.get("/")
async def read_root(headers: MyHeaders = Header()):
    return {"headers": headers}

client = TestClient(app)

def test_underscore_headers():
    # Test with hyphenated header (should work)
    response_hyphen = client.get("/", headers={"my-header": "hyphen-value"})
    print(f"Hyphen: {response_hyphen.json()}")
    assert response_hyphen.json() == {"headers": {"my_header": "hyphen-value"}}

    # Test with underscore header (should NOT work if convert_underscores=True)
    response_underscore = client.get("/", headers={"my_header": "underscore-value"})
    print(f"Underscore: {response_underscore.json()}")
    assert response_underscore.json() == {"headers": {"my_header": None}}

    # Test with convert_underscores=False
    # We need a different endpoint for this
    return

@app.get("/no-convert")
async def read_root_no_convert(headers: MyHeaders = Header(convert_underscores=False)):
    return {"headers": headers}

def test_no_convert_underscore_headers():
    # Test with underscore header (should work)
    response_underscore = client.get("/no-convert", headers={"my_header": "underscore-value"})
    print(f"Underscore (no-convert): {response_underscore.json()}")
    assert response_underscore.json() == {"headers": {"my_header": "underscore-value"}}

if __name__ == "__main__":
    try:
        test_underscore_headers()
        print("test_underscore_headers passed")
    except AssertionError as e:
        print(f"test_underscore_headers failed")

    try:
        test_no_convert_underscore_headers()
        print("test_no_convert_underscore_headers passed")
    except AssertionError as e:
        print(f"test_no_convert_underscore_headers failed")
